/* Cricket Greatness Lab: all published rankings are computed from the ingested source ledger. */
(()=>{'use strict';
const $=(s)=>document.querySelector(s),fmtLabel={odi:'One-Day International',test:'Test Cricket',t20i:'T20 International',test_odi:'Tests + ODIs',all_three:'All Three Formats'},baselineWeight={odi:.58,test:.32,t20i:.78};
let report=window.CGL_REPORT||null,focus=window.CGL_FOCUS||[],allInnings=null,view='overview',sortKey='index',sortDesc=true,metric='index',query='',country='All',region='All',minInnings=25,weight=null,selectedPlayer=null,c1=null,c2=null,cf='odi',cmode='career',cVenue='All',cOpp='',msort='date';
const fmt=n=>fmtLabel[n]||n, e=x=>String(x??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;'),num=(v,d=0)=>v===null||v===undefined||!isFinite(+v)?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}),r2=v=>v===null||v===undefined?'—':num(v,2),t=(value,small)=>`<div class="stat"><div class="lab">${e(value)}</div><div class="value">${e(small)}</div></div>`,sections={overview:['Who was <em>truly</em> the greatest?','Behind every great innings are the conditions, opposition, era and teammates that shaped it.'],odi:['The ODI <em>greatness</em> debate','Chasing, scoring tempo, bowling quality, same-match comparisons and fifty-over rules.'],test:['The greatest <em>Test</em> batters','Measure survival, difficult conditions, unfamiliar venues and opposition attacks across eras.'],t20i:['The T20I <em>impact</em> index','Strike rate and wicket preservation measured against the scoring environment of each innings.'],test_odi:['Excellence in <em>both</em> forms','An equal-format comparison of batters who qualify in Tests and ODIs.'],all_three:['Greatness across <em>three</em> formats','An equal-weight geometric comparison. Eligibility and history are critical caveats.'],compare:['Batter <em>comparison</em> lab','Compare the same age, same number of observed innings, matching opponents and locations.'],matches:['Every innings, <em>in context</em>','Search the actual source-backed batting ledger, then see what teammates scored in the same match.'],methodology:['How the index <em>works</em>','Documented formulas, important statistical assumptions, and visible model limitations.'],coverage:['Source data, <em>without</em> the spin','Every claim of coverage, missing matches, source licences, and the boundary of what is supported.']};
function status(){let has=!!report?.manifest?.matchCount;$('#header-status').textContent=has?'COMPUTED FROM MATCHES':'AWAITING FIRST BUILD';$('#side-status').textContent=has?`${num(report.manifest.matchCount)} observed matches`:'No match archive ingested';$('#data-notice').className='notice'+(has?' ok':'');$('#data-notice').innerHTML=has?`<strong>Verified-record build:</strong> ${num(report.manifest.matchCount)} source matches, ${num(report.manifest.playerCount)} observed players, ${e(report.manifest.earliestDate)}–${e(report.manifest.latestDate)}. ${report.careerValidation ? `ICC retired-career checks: ${num(report.careerValidation.passingCareers)}/${num(report.careerValidation.checkedCareers)} matched. ` : ''}${report.metadata?.isAllTimeEligible?'Historical scorecard records imported.':report?.scorecardParity?.hasHistorical?'Historical innings backfilled; complete all-time coverage remains UNVERIFIED.':'Pre-2002 historical innings have not yet been imported.'}`:`<strong>Research system installed; historical match data not yet imported.</strong> No Claude scores, demonstration rankings or synthetic match results are shown. Run the included GitHub workflow; it downloads BOTH historical scorecard innings and modern deliveries, merges them, checks reference careers and publishes new results.`}
function header(page){const [h,p]=sections[page]||sections.overview;$('#page-heading').innerHTML=h;$('#page-description').textContent=p;$('#breadcrumb').textContent=(fmtLabel[page]||page).replace(/_/g,' ').toUpperCase();document.querySelectorAll('nav button[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page))}
function nav(page,extra){view=page;window.location.hash=page==='profile'?'#profile/'+encodeURIComponent(extra):'#'+page;if(page==='profile')selectedPlayer=extra;draw();if(window.innerWidth<740)$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'instant'})}
function empty(tit='No independently computed rankings yet'){return `<div class="empty"><strong>${e(tit)}</strong><p>Once the original international match archives have been processed, this panel will show actual calculated values for each qualifying batter. The site never fills missing observations with estimates from the supplied Claude report.</p><code>python -m pipeline.ingest --download</code><p style="margin:10px 0 0"><code>python -m pipeline.model</code></p></div>`}
function stats(cards){return '<div class="stat-grid">'+cards.map(x=>`<div class="stat"><div class="lab">${e(x[0])}</div><div class="value">${e(x[1])}</div><div class="sub">${e(x[2]||'')}</div></div>`).join('')+'</div>'}
function bar(items,key='index'){if(!items.length)return empty('Leaderboard awaits independent calculation');let mx=Math.max(110,...items.slice(0,10).map(x=>Number(x[key])||0));return `<div class="card chart-card"><div class="chart-caption"><strong>Leading batters · observed sample</strong><span class="soft">${e(key==='greatnessIndex'?'Career Greatness':'Batting Quality')} index</span></div><div class="bar-chart">`+items.slice(0,10).map((x,i)=>`<div class="barrow"><div class="barname" title="${e(x.name)}">${i+1}. ${e(x.name)}</div><div class="bartrack"><div class="barvalue" style="width:${Math.max(1,Math.min(100,(Number(x[key])||0)/mx*100)).toFixed(2)}%"></div></div><div class="barlabel">${num(x[key],1)}</div></div>`).join('')+'</div></div>'}
function fmtLeaders(f){return report?.rankings?.[f]||[]}
function eraContext(f){const years=report?.eraTrends?.[f]||[];if(!years.length)return empty('Era-scoring trends require source archives');let last=years.slice(-27),W=740,H=205,valid=last.filter(x=>x.runsPer100Balls!=null);if(!valid.length)return '';let lo=Math.min(...valid.map(x=>x.runsPer100Balls)),hi=Math.max(...valid.map(x=>x.runsPer100Balls));let mapx=i=>45+(i/(last.length-1||1))*650,mapy=v=>H-34-(v-lo)/(hi-lo||1)*(H-80);let points=last.map((x,i)=>`${mapx(i).toFixed(1)},${mapy(x.runsPer100Balls).toFixed(1)}`).join(' ');let labels=last.filter((_,i)=>i===0||i===last.length-1||i%5===0).map(y=>`<text x="${mapx(last.indexOf(y))}" y="${H-8}" font-size="11" fill="#687c75" text-anchor="middle">${y.year}</text>`).join('');let rows=years.slice().reverse().slice(0,16).map(x=>`<tr><td>${x.year}</td><td class="num">${num(x.innings)}</td><td class="num">${num(x.runsPer100Balls,1)}</td><td class="num">${num(x.runsPerDismissal,1)}</td><td>${e(x.odiRuleRegime||'Year-level baseline')}</td></tr>`).join('');return `<section class="section"><div class="section-heading"><h2>Batting-friendly eras · scoring conditions</h2><span class="sub">Observed source batters only; composition of teams and opponents may change</span></div><div class="card chart-card"><div class="chart-caption"><strong>Runs per 100 legal balls faced by recorded batters</strong><span class="soft">Not an adjusted pitch rating</span></div><svg viewBox="0 0 ${W} ${H}" class="linegraph" role="img" aria-label="Runs per hundred balls by calendar year"><line x1="45" y1="${H-34}" x2="700" y2="${H-34}" stroke="#cedbd6"/><polyline points="${points}" fill="none" stroke="#14806a" stroke-width="3" stroke-linejoin="round"/>${last.map((x,i)=>`<circle cx="${mapx(i)}" cy="${mapy(x.runsPer100Balls)}" r="3" fill="#14806a"><title>${x.year}: ${x.runsPer100Balls} runs per 100 balls · ${x.innings} innings</title></circle>`).join('')}${labels}<text x="6" y="30" font-size="11" fill="#687c75">${num(hi,0)}</text><text x="6" y="${H-30}" font-size="11" fill="#687c75">${num(lo,0)}</text></svg></div><div class="table-wrap"><table class="rank-table"><thead><tr><th>Year</th><th class="num">Observed innings</th><th class="num">Runs / 100 balls</th><th class="num">Runs / dismissal</th><th>Rules period</th></tr></thead><tbody>${rows}</tbody></table></div><p class="footnote">Actual calendar-year changes also reflect who played, available matches and opposition composition. The ODI rule dates are labels only; causal impact has not yet been estimated.</p></section>`}

function showOverview(){let mf=report?.manifest||{},leaders=Object.entries({odi:fmtLeaders('odi'),test:fmtLeaders('test'),t20i:fmtLeaders('t20i')});let body=stats([['Observed international matches',num(mf.matchCount||0),'Not all matches ever played'],['Delivery-recorded batters',num(mf.playerCount||0),'Cricsheet identifiers'],['Test / ODI / T20I',mf.byFormat?`${num(mf.byFormat.test||0)} / ${num(mf.byFormat.odi||0)} / ${num(mf.byFormat.t20i||0)}`:'—','Men’s international matches'],['Data through',mf.latestDate||'Not loaded','Last match in ingested source']]);
body+=`<div class="takeaway"><div><small>THE RESEARCH QUESTION</small><h2>Greatness is performance above expectation, not just a high batting average.</h2><p>Our three distinct outputs are quality, team carry and career greatness. We evaluate each format separately, with sensitivity checks on how strike rate and wicket preservation are weighted.</p></div><div class="evidence"><div class="insight"><strong>Quality</strong> · Era-, role- and match-aware batting performance; opponent-bowling adjustment where available.</div><div class="insight"><strong>Carry</strong> · Batting relative to expected same-innings teammates, plus team run share.</div><div class="insight"><strong>Greatness</strong> · Quality supported by innings volume and cumulative runs above expectation.</div></div></div>`;
if(report?.scorecardParity?.hasHistorical){const hp=report.scorecardParity;body+=`<section class="section"><div class="section-heading"><h2>Historical era-normalized scorecard rankings</h2><span class="sub">First-generation model · historical completeness NOT independently certified</span></div><div class="cards-three">${['test','odi','t20i'].map(f=>{const a=hp.rankings?.[f]||[];const p=a[0];return `<div class="method-card"><div class="k-label">${e(fmt(f))}</div><h3>${p?e(p.name):'Not enough scorecards'}</h3><p>${p?`Era-parity ${num(p.index,1)} · ${num(p.innings)} innings · ${num(p.historicInnings)} historic`:'No eligible observed innings'}</p></div>`}).join('')}</div><p class="footnote">These comparisons use one common scorecard-only model across old and new eras. Opponent-bowler exposure, batting-order controls and official-match completeness are not yet verified. Do not interpret the leaders as established all-time winners.</p></section>`}
body+=`<section class="section"><div class="section-heading"><h2>Best batter in each format</h2><span class="sub">Current observed data only; not a historical all-time verdict</span></div><div class="cards-three">${leaders.map(([f,items])=>`<button class="link-card" data-goto="${f}"><div class="k-label">${e(fmt(f))}</div><strong>${items.length?e(items[0].name):'Awaiting observations'}</strong><p>${items.length?`Quality ${num(items[0].index,1)} · ${num(items[0].innings)} innings`:'No verified ranking calculated'}</p><div class="arrow">View analysis →</div></button>`).join('')}</div></section>`;
body+=`<section class="section"><div class="section-heading"><h2>Explore the research</h2><span class="sub">Comparisons, match records and data transparency</span></div><div class="cards-three">${[['compare','Batter comparison','Kohli vs Gill, Tendulkar vs Kohli, matched careers'],['matches','Match explorer','Same-match teammates, opposition and conditions'],['methodology','Open methodology','Exact formulas and assumptions']].map(([id,name,desc])=>`<button class="link-card" data-goto="${id}"><div class="k-label">RESEARCH TOOL</div><strong>${name}</strong><p>${desc}</p><div class="arrow">Explore →</div></button>`).join('')}</div></section>`;
body+=`<section class="section"><div class="section-heading"><h2>What we can and cannot conclude</h2></div><div class="cards-two"><div class="call"><h3 class="accent">Measured where data exists</h3><p>Player-level scorecards, batting tempo, survival, contemporary baselines, the team burden and opponent-bowler exposure. Every recorded innings remains traceable to its match file.</p></div><div class="call"><h3>Not yet established for all time</h3><p>Bradman versus Smith or Richards versus Kohli cannot be settled solely from post-2001 deliveries. Historical Test and early ODI scorecards are essential and must be incorporated on an equivalent model and with provenance.</p></div></div></section>`;return body}
function metricVal(x){if(region!=='All'&&x.conditions)return x.conditions[region]?.index??null;if(metric==='sensitivity'){let w=weight??baselineWeight[view];if(!x.runIndex||!x.survivalIndex)return null;return 100*Math.exp((w*Math.log(x.runIndex/100)+(1-w)*Math.log(x.survivalIndex/100))*x.innings/(x.innings+28))}return x[metric]??null}
function rankingRows(items){let sub=items.filter(x=>x.innings>=minInnings&&(country==='All'||x.team===country)&&x.name.toLowerCase().includes(query.toLowerCase())).map(x=>({...x,shownValue:metricVal(x)})).filter(x=>x.shownValue!==null);sub.sort((a,b)=>{let av=sortKey==='shownValue'?a.shownValue:a[sortKey],bv=sortKey==='shownValue'?b.shownValue:b[sortKey];if(typeof av==='string')return (sortDesc?-1:1)*bv.localeCompare(av);return (sortDesc?-1:1)*((+bv||0)-(+av||0))});return sub}
function formatPage(f){let all=fmtLeaders(f);let top=all[0];let m=report?.manifest||{};let countries=[...new Set(all.map(x=>x.team))].sort();let mode=region!=='All'?'Run-scoring index in '+region:metric==='sensitivity'?'Sensitivity-adjusted quality':metric==='greatnessIndex'?'Career Greatness Index':metric==='carryIndex'?'Team Carry Index':metric==='runsAboveExpected'?'Runs Above Expected':'Batting Quality Index';let body=top?`<div class="takeaway"><div><small>PROVISIONAL FINDING · OBSERVED MATCHES</small><h2>${e(top.name)} leads this available-sample ${e(fmt(f))} ranking.</h2><p>The raw aggregate is calculated directly from observed innings, not reconstructed from another report. A complete all-time claim must wait for every historic scorecard and match reconciliation.</p></div><div class="evidence"><div class="insight">Quality index: <strong>${num(top.index,1)}</strong> · ${num(top.innings)} recorded innings</div><div class="insight">Same-innings carry: <strong>${num(top.carryIndex,1)}</strong> · independent teammate comparison</div><div class="insight">Runs above model expectation: <strong>${num(top.runsAboveExpected,0)}</strong></div></div></div>`:empty();
body+=stats([['Ingested matches',num(m.byFormat?.[f]||0),'Not the all-time format total'],['Eligible batters',num(all.length),'Default minimum innings rule'],['Top Quality',top?num(top.index,1):'—','100 = context-matched baseline'],['Leading carry',all.length?`${e([...all].sort((a,b)=>b.carryIndex-a.carryIndex)[0].name)}`:'—','Same-innings relative impact']]);
body+=`<section class="section"><div class="section-heading"><h2>Rankings · ${e(fmt(f))}</h2><span class="sub">Click a name for career details</span></div><div class="toolbar"><div class="field grow"><label>Search batter</label><input id="search-batter" placeholder="Search all observed players" value="${e(query)}"/></div><div class="field"><label>National team</label><select id="country-filter"><option>All</option>${countries.map(x=>`<option ${country===x?'selected':''}>${e(x)}</option>`).join('')}</select></div><div class="field"><label>Location</label><select id="region-filter">${['All','India','SENA','Other'].map(x=>`<option ${region===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Index</label><select id="metric-filter">${[['index','Quality'],['greatnessIndex','Career Greatness'],['carryIndex','Team Carry'],['runsAboveExpected','Runs Above Expected'],['sensitivity','Sensitivity model']].map(([id,label])=>`<option value="${id}" ${metric===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>Min innings</label><select id="minimum-filter">${[10,20,25,40,60,100].map(x=>`<option value="${x}" ${minInnings===x?'selected':''}>${x}</option>`).join('')}</select></div></div>`;
if(metric==='sensitivity'&&region==='All'){let w=weight??baselineWeight[f];body+=`<div class="slider-box"><span>Wicket preservation</span><input type="range" id="weight-control" min="5" max="95" step="5" value="${Math.round(w*100)}"/><span>Run scoring</span><strong>${Math.round(w*100)}%</strong></div>`}
let subset=rankingRows(all);body+=all.length?`<div class="table-wrap"><table class="rank-table"><thead><tr><th>#</th><th><button data-sort="name">Batter ↕</button></th><th>Country</th><th class="num"><button data-sort="innings">Inns ↕</button></th><th class="num"><button data-sort="runs">Runs ↕</button></th><th class="num">Average</th><th class="num">SR</th><th class="num"><button data-sort="shownValue">${e(mode)} ↕</button></th><th class="num">Quality 90% interval</th><th class="num">Team Carry</th><th class="num">Runs Above Par</th><th class="num">Team Share %</th></tr></thead><tbody>`+subset.slice(0,300).map((x,i)=>`<tr><td class="rank">${i+1}</td><td><button class="player-link" data-player="${e(x.playerId)}">${e(x.name)}</button></td><td>${e(x.team)}</td><td class="num">${num(x.innings)}</td><td class="num">${num(x.runs)}</td><td class="num">${r2(x.average)}</td><td class="num">${r2(x.strikeRate)}</td><td class="num primary-val">${num(x.shownValue,1)}</td><td class="num">${x.ci90?`${num(x.ci90[0],1)}–${num(x.ci90[1],1)}`:'—'}</td><td class="num">${num(x.carryIndex,1)}</td><td class="num">${num(x.runsAboveExpected)}</td><td class="num">${num(x.teamRunShare,1)}</td></tr>`).join('')+`</tbody></table></div><p class="footnote">${subset.length} matching players. India/SENA/Other ranking uses run-scoring efficiency only; it is NOT the same metric as the full batting-quality index. The 90% interval is a conditional match-block bootstrap of Quality (not applicable to other selected metrics); it does not capture baseline/model uncertainty. The default index is provisional, not causal.</p>`:empty('No source-backed ranking in this format yet');body+=`</section>`;
body+=`<section class="section"><div class="section-heading"><h2>Top batting-quality scores</h2><span class="sub">Players meeting minimum eligibility</span></div>${bar(all.slice(0,12))}</section><section class="section"><div class="cards-two"><div class="call"><h3>Measuring skill versus the bowling attack</h3><p>In delivery-covered matches, the model uses the bowling performances of opponents in nearby years, with shrinkage toward the format baseline. This is observational, not a causal measure of bowler difficulty.</p></div><div class="call"><h3>Measuring the burden of carrying a team</h3><p>The team-carry index compares actual runs with the expectation for the batter relative to the expectation and performance of other batters in that innings. Also inspect team run share and cumulative runs above expectation.</p></div></div></section>`;body+=eraContext(f);if(report?.scorecardParity?.hasHistorical){const historic=report.scorecardParity.rankings?.[f]||[];body+=`<section class="section"><div class="section-heading"><h2>Historical scorecard-parity · separate index</h2><span class="sub">Era-only common-denominator model; no reliable historic batting-order controls</span></div><p class="footnote">${e(report.scorecardParity.caution)}</p>`+(historic.length?`<div class="table-wrap"><table class="rank-table"><thead><tr><th>#</th><th>Batter</th><th>Team</th><th class="num">Inns</th><th class="num">Historical innings</th><th class="num">Same-team carry</th><th class="num">Era-parity score</th></tr></thead><tbody>`+historic.slice(0,60).map((p,i)=>`<tr><td>${i+1}</td><td>${e(p.name)}</td><td>${e(p.team)}</td><td class="num">${num(p.innings)}</td><td class="num">${num(p.historicInnings)}</td><td class="num">${num(p.teamCarryIndex,1)}</td><td class="num primary-val">${num(p.index,1)}</td></tr>`).join('')+`</tbody></table></div>`:empty('No eligible historical scorecard-parity rows'))+'</section>'}return body}
function combinedPage(id){let all=report?.combined?.[id]||[],top=all[0],need=id==='test_odi'?['test','odi']:['test','odi','t20i'];let body=top?`<div class="takeaway"><div><small>MULTI-FORMAT · OBSERVED SAMPLE ONLY</small><h2>${e(top.name)} leads the equal-format composite.</h2><p>Each format receives equal weight through the geometric mean. Tests and ODIs use a shared comparison frame only when genuinely comparable historical scorecard data exists.</p></div><div class="evidence">${need.map(f=>`<div class="insight">${fmt(f)} · <strong>${num(top.formats[f],1)}</strong></div>`).join('')}</div></div>`:empty();body+=stats([['Eligible batters',num(all.length),'Must meet qualification in every format'],['Leader Quality',top?num(top.index,1):'—','Geometric mean'],['Leader Greatness',top?num(top.greatnessIndex,1):'—','Volume-sensitive composite'],['Historical archive',report?.scorecardParity?.hasHistorical?'Backfilled, unverified':'Not imported','Not a universal verdict']]);body+=`<section class="section"><div class="section-heading"><h2>Multi-format leaderboard</h2><span class="sub">Equal weight per eligible format</span></div>`;body+=all.length?`<div class="table-wrap"><table class="rank-table"><thead><tr><th>#</th><th>Batter</th><th>Team</th>${need.map(x=>`<th class="num">${e(fmt(x))}</th>`).join('')}<th class="num">Quality</th><th class="num">Career Greatness</th><th class="num">Innings</th></tr></thead><tbody>`+all.slice(0,300).map((x,i)=>`<tr><td class="rank">${i+1}</td><td><button class="player-link" data-player="${e(x.playerId)}">${e(x.name)}</button></td><td>${e(x.team)}</td>${need.map(f=>`<td class="num">${num(x.formats[f],1)}</td>`).join('')}<td class="num primary-val">${num(x.index,1)}</td><td class="num">${num(x.greatnessIndex,1)}</td><td class="num">${num(x.totalInnings)}</td></tr>`).join('')+`</tbody></table></div>`:empty('No eligible multi-format batter calculations yet');body+='</section><section class="section">'+bar(all)+'</section>';body+=`<p class="footnote">An athlete who did not play T20I must be excluded from the three-format leaderboard, not scored zero. The Tests+ODIs leaderboard is the historically more appropriate comparison for players whose careers preceded T20I.</p>`;if(report?.scorecardParity?.hasHistorical){let hist=report.scorecardParity.combined?.[id]||[];body+=`<section class="section"><div class="section-heading"><h2>Historical scorecard-parity composite</h2><span class="sub">Separate weaker method; do not conflate with the modern model</span></div><p class="footnote">${e(report.scorecardParity.caution)}</p>`+(hist.length?`<div class="table-wrap"><table class="rank-table"><thead><tr><th>#</th><th>Batter</th>${need.map(f=>`<th class="num">${e(fmt(f))}</th>`).join('')}<th class="num">Composite</th></tr></thead><tbody>`+hist.slice(0,60).map((p,i)=>`<tr><td>${i+1}</td><td>${e(p.name)}</td>${need.map(f=>`<td class="num">${num(p.formats[f],1)}</td>`).join('')}<td class="num primary-val">${num(p.index,1)}</td></tr>`).join('')+'</tbody></table></div>':empty('No combined historical candidates'))+'</section>'}return body}
function playerInfo(id){let all=[...(report?.players||[]),...(report?.historicalPlayers||[])];return all.find(x=>x.playerId===id)||all.find(x=>x.name===id)}
function profilePage(id){let p=playerInfo(id);if(!p)return empty('Batter not in observed scorecards');if(!p.formats){const score=Object.entries(report?.scorecardParity?.rankings||{}).flatMap(([f,rows])=>rows.filter(z=>z.playerId===id).map(z=>({...z,format:f})));return `<div class="takeaway"><div><small>HISTORICAL SCORECARD-ONLY PROFILE</small><h2>${e(p.name)}</h2><p>Includes the available historical records and common era-adjusted baseline. Historical ball-by-ball bowling exposure and batting order are not available; do not compare these values directly with the modern Quality index.</p></div><div class="evidence">${score.map(x=>`<div class="insight">${fmt(x.format)} · <strong>${num(x.index,1)}</strong> era-parity · ${num(x.innings)} observed innings</div>`).join('')}</div></div><section class="section"><h2>Common-denominator batting analysis</h2><div class="table-wrap"><table class="rank-table"><thead><tr><th>Format</th><th class="num">Innings</th><th class="num">Runs</th><th class="num">Average</th><th class="num">Era-parity score</th><th class="num">Teammate carry</th></tr></thead><tbody>${score.map(x=>`<tr><td>${fmt(x.format)}</td><td class="num">${num(x.innings)}</td><td class="num">${num(x.runs)}</td><td class="num">${num(x.average,1)}</td><td class="num primary-val">${num(x.index,1)}</td><td class="num">${num(x.teamCarryIndex,1)}</td></tr>`).join('')}</tbody></table></div><p class="footnote">Source: publicly posted historical innings archive plus non-overlapping Cricsheet records. Not verified against every official match.</p></section><section class="section"><button class="link-card" data-goto="compare"><strong>Compare with another batter →</strong><p>The career comparison lab includes selected historical batting-innings extracts and can align innings or ages where birthdays are known.</p></button></section>`} let rows=Object.values(p.formats);let body=`<div class="takeaway"><div><small>BATTER PROFILE · SOURCE OBSERVATIONS</small><h2>${e(p.name)}</h2><p>Team: ${e(p.team)}. Only formats and innings that were actually included in the data build are shown. Historical careers may have incomplete coverage.</p></div><div class="evidence">${rows.map(x=>`<div class="insight">${e(fmt(x.format))}: <strong>${num(x.index,1)}</strong> quality · ${num(x.innings)} observed innings</div>`).join('')}</div></div>`;body+=stats([['Recorded international runs',num(rows.reduce((a,x)=>a+x.runs,0)),'Only observed matches'],['Recorded innings',num(rows.reduce((a,x)=>a+x.innings,0)),'Across covered formats'],['Average Career Greatness',num(rows.reduce((a,x)=>a+x.greatnessIndex,0)/(rows.length||1),1),'Non-official composite'],['Approx. source coverage',rows.some(x=>x.range[0]<'2004-01-01')?'Partial':'Modern era','See data boundaries']]);body+=`<section class="section"><div class="section-heading"><h2>Format-by-format performance</h2></div><div class="table-wrap"><table class="rank-table"><thead><tr><th>Format</th><th class="num">Inns</th><th class="num">Runs</th><th class="num">Avg</th><th class="num">SR</th><th class="num">Quality</th><th class="num">Carry</th><th class="num">Greatness</th><th class="num">Bowling adj. coverage</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${e(fmt(x.format))}</td><td class="num">${num(x.innings)}</td><td class="num">${num(x.runs)}</td><td class="num">${r2(x.average)}</td><td class="num">${r2(x.strikeRate)}</td><td class="num primary-val">${num(x.index,1)}</td><td class="num">${num(x.carryIndex,1)}</td><td class="num">${num(x.greatnessIndex,1)}</td><td class="num">${num(x.bowlerCoveragePct,1)}%</td></tr>`).join('')}</tbody></table></div></section>`;body+=`<section class="section"><div class="section-heading"><h2>Conditions and match context</h2><span class="sub">Regional indices are runs/expected-runs, not full Quality indices</span></div><div class="cards-three">${rows.map(x=>`<div class="method-card"><div class="k-label">${e(fmt(x.format))}</div><h3>Home / Away / SENA</h3><p>Home: ${num(x.home?.index,1)} run-rate · ${num(x.home?.inns)} inns<br>Away: ${num(x.away?.index,1)} run-rate · ${num(x.away?.inns)} inns<br>SENA: ${num(x.conditions?.SENA?.index,1)} run-rate · ${num(x.conditions?.SENA?.inns)} inns<br>World Cups: ${num(x.worldCup?.index,1)} run-rate · ${num(x.worldCup?.inns)} inns</p></div>`).join('')}</div></section>`;body+=`<section class="section"><div class="cards-two"><div class="call"><h3>Opposition difficulty (observational)</h3><p>These matches yield a bowling-difficulty signal based on nearby-year bowler run suppression and wicket rate. A positive number indicates exposure to stronger-performing attacks in this database.</p>${rows.map(x=>`<div class="k-label">${fmt(x.format)}: ${num(x.avgBowlerDifficulty,3)}</div>`).join('')}</div><div class="call"><h3>Innings and peer impact</h3><p>Run share is the portion of team totals from that batter in the covered innings. Peer lift compares their scoring to teammate-relative expectations in the same innings.</p>${rows.map(x=>`<div class="k-label">${fmt(x.format)}: ${num(x.teamRunShare,1)}% team runs · ${num(x.matchPeerLift)} peer-lift runs</div>`).join('')}</div></div></section>`;body+=`<section class="section"><button class="link-card" data-goto="compare"><strong>Compare this player with another →</strong><p>Use matched age, innings and same-match samples.</p></button></section>`;const hr=(report?.scorecardParity?.rankings||{});const matched=Object.entries(hr).flatMap(([f,rank])=>(rank||[]).filter(x=>x.name===p.name&&x.team===p.team).map(x=>({...x,format:f})));
if(matched.length){body+=`<section class="section"><div class="section-heading"><h2>Historical and modern careers: scorecard-common-denominator comparison</h2><span class="sub">All available innings, not just Cricsheet deliveries</span></div><p class="footnote">These historical figures use a different common-denominator model from the modern Quality index above. They are NOT interchangeable and historical completeness is NOT certified.</p><div class="table-wrap"><table class="rank-table"><thead><tr><th>Format</th><th class="num">Available inns</th><th class="num">Observed runs</th><th class="num">Historical-only inns</th><th class="num">Era-parity</th><th class="num">Peer-carry</th></tr></thead><tbody>${matched.map(x=>`<tr><td>${e(fmt(x.format))}</td><td class="num">${num(x.innings)}</td><td class="num">${num(x.runs)}</td><td class="num">${num(x.historicInnings)}</td><td class="num">${num(x.index,1)}</td><td class="num">${num(x.teamCarryIndex,1)}</td></tr>`).join('')}</tbody></table></div></section>`}
const career=(report?.careerValidation?.checks||[]).filter(x=>x.player===p.name);
if(career.length){body+=`<section class="section"><div class="section-heading"><h2>Career scorecard reconciliation</h2></div><div class="cards-two">${career.map(x=>`<div class="insight"><strong>${e(fmt(x.format))}: ${num(x.observedRuns)} / ${num(x.referenceRuns)} recorded runs</strong><p>Difference: ${num(x.deltaRuns)} · ${x.careerRunsReconciled?'ICC run-total matched (other checks still needed)':'Career data MISMATCH — investigate source coverage'}</p><a href="${e(x.referenceUrl)}" rel="noopener" target="_blank">Official ICC reference</a></div>`).join('')}</div></section>`}
return body}
function optionsPlayers(){return [...(report?.players||[]),...(report?.historicalPlayers||[])].slice().sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${e(p.playerId)}">${e(p.name)} · ${e(p.team)}</option>`).join('')}
function chooseDefaults(){let players=[...(report?.players||[]),...(report?.historicalPlayers||[])];let locate=name=>players.find(x=>x.name===name)?.playerId;if(!c1)c1=locate('Virat Kohli')||players[0]?.playerId;if(!c2)c2=locate('Shubman Gill')||players[1]?.playerId;if(c1===c2&&players.length>1)c2=players.find(x=>x.playerId!==c1)?.playerId}
async function loadAllInnings(){if(allInnings)return allInnings;if(!('DecompressionStream' in window))return focus;try{const res=await fetch('data/innings.json.gz');if(!res.ok)throw Error('Not found');const stream=res.body.pipeThrough(new DecompressionStream('gzip'));allInnings=await new Response(stream).json();allInnings.push(...(report?.historicalFocus||[]));return allInnings}catch(_){return focus}}
function comparisonRows(all,id,f){return all.filter(r=>r.p===id&&r.f===f).sort((a,b)=>a.d.localeCompare(b.d)||a.m.localeCompare(b.m))}
function paired(all){let ra=comparisonRows(all,c1,cf),rb=comparisonRows(all,c2,cf);if(cVenue!=='All'){ra=ra.filter(x=>x.reg===cVenue);rb=rb.filter(x=>x.reg===cVenue)}if(cOpp){ra=ra.filter(x=>x.o.toLowerCase().includes(cOpp.toLowerCase()));rb=rb.filter(x=>x.o.toLowerCase().includes(cOpp.toLowerCase()))}if(cmode==='sameAge'){let aa=ra.filter(x=>x.age!=null),bb=rb.filter(x=>x.age!=null);if(aa.length&&bb.length){let max=Math.min(Math.max(...aa.map(x=>x.age)),Math.max(...bb.map(x=>x.age)));ra=aa.filter(x=>x.age<=max);rb=bb.filter(x=>x.age<=max)}else{ra=[];rb=[]}}
if(cmode==='sameInnings'){let n=Math.min(ra.length,rb.length);ra=ra.slice(0,n);rb=rb.slice(0,n)}if(cmode==='sharedMatches'){const shared=new Set(ra.map(x=>x.m));let sh=new Set(rb.filter(x=>shared.has(x.m)).map(x=>x.m));ra=ra.filter(x=>sh.has(x.m));rb=rb.filter(x=>sh.has(x.m))}return [ra,rb]}
function metrics(rows){let runs=rows.reduce((a,x)=>a+x.r,0),balls=rows.reduce((a,x)=>a+(x.b||0),0),outs=rows.reduce((a,x)=>a+x.x,0),hasHistorical=rows.some(x=>x.s===1),er=rows.reduce((a,x)=>a+(x.er||0),0),share=0;return {inns:rows.length,runs,avg:outs?runs/outs:null,sr:hasHistorical?null:balls?100*runs/balls:null,rate:hasHistorical?null:er?100*(runs+25)/(er+25):null,carry:hasHistorical?null:rows.length?100*(runs+25)/(rows.reduce((a,x)=>a+(x.er||0)*(x.pr||1),0)+25):null,above:hasHistorical?null:runs-er,share}}
function miniCurve(a,b){let maxy=Math.max(10,a.reduce((s,x)=>s+x.r,0),b.reduce((s,x)=>s+x.r,0));let maxn=Math.max(a.length,b.length,2);let path=(rows)=>{let s=0,pts=[[35,230]];for(let i=0;i<rows.length;i++){s+=rows[i].r;pts.push([35+(i+1)/(maxn)*660,230-s/maxy*195])}return pts.map((p,i)=>(i?'L':'M')+p.map(z=>z.toFixed(1)).join(',')).join(' ')};return `<svg class="linegraph" viewBox="0 0 730 260" role="img" aria-label="Cumulative observed runs by innings"><line x1="35" y1="230" x2="695" y2="230" stroke="#b4cfc2"/><line x1="35" y1="35" x2="35" y2="230" stroke="#b4cfc2"/><path d="${path(a)}" fill="none" stroke="#147d68" stroke-width="3"/><path d="${path(b)}" fill="none" stroke="#c69352" stroke-width="3"/><text x="38" y="22" font-size="11" fill="#84958f">Cumulative runs</text><text x="690" y="248" text-anchor="end" fill="#84958f" font-size="11">Observed innings →</text></svg>`}
function comparisonOutput(all){let a=playerInfo(c1),b=playerInfo(c2);if(!a||!b)return empty();let [ra,rb]=paired(all);if(!ra.length||!rb.length)return empty('No comparable innings for this filter in the loaded archive');let x=metrics(ra),y=metrics(rb);let rows=[['Observed innings',x.inns,y.inns],['Observed runs',x.runs,y.runs],['Batting average',x.avg,y.avg],['Strike rate',x.sr,y.sr],['Run-scoring index',x.rate,y.rate],['Same-innings carry index',x.carry,y.carry],['Runs above expected',x.above,y.above]];return `<div class="section"><div class="section-heading"><h2>Comparison results · ${e(fmt(cf))}</h2><span class="sub">Actual source innings; compare like-for-like samples</span></div><div class="card card-pad"><div class="metric-battle"><strong>${e(a.name)}</strong><div class="metric-name">METRIC</div><strong>${e(b.name)}</strong></div>${rows.map(([label,u,v])=>`<div class="metric-battle"><div class="${u>v?'winner':''}">${num(u,1)}</div><div class="metric-name">${e(label)}</div><div class="${v>u?'winner':''}">${num(v,1)}</div></div>`).join('')}</div><p class="split-note">Same-age matching requires a verified birth date; shared-match matching requires a recorded shared match. If either sample contains historical scorecards, strike rate and bowler-adjusted runs are intentionally unavailable rather than invented. Historical era-parity scores above use a separate whole-career model, not the modern delivery-only Quality Index.</p></div><section class="section"><div class="section-heading"><h2>Career trajectories</h2><span class="sub">Cumulative runs · selected sample</span></div><div class="card chart-card"><div style="display:flex;gap:18px;font-size:11px"><span style="color:#147d68">● ${e(a.name)}</span><span style="color:#c69352">● ${e(b.name)}</span></div>${miniCurve(ra,rb)}</div></section>`}
function comparisonPage(){if(!report?.players?.length)return empty();chooseDefaults();let body=`<div class="compare-choices"><div class="versus"><strong>BATTER ONE</strong><select id="compare-one">${optionsPlayers()}</select></div><div class="versus"><strong>BATTER TWO</strong><select id="compare-two">${optionsPlayers()}</select></div></div><div class="toolbar" style="margin-top:13px"><div class="field"><label>Format</label><select id="compare-format">${['odi','test','t20i'].map(f=>`<option value="${f}" ${cf===f?'selected':''}>${fmt(f)}</option>`).join('')}</select></div><div class="field"><label>Career matching</label><select id="compare-mode">${[['career','Observed careers'],['sameAge','Up to same age'],['sameInnings','Same number of innings'],['sharedMatches','Only shared matches']].map(([id,txt])=>`<option value="${id}" ${cmode===id?'selected':''}>${txt}</option>`).join('')}</select></div><div class="field"><label>Location</label><select id="compare-venue">${['All','India','SENA','Other'].map(x=>`<option ${x===cVenue?'selected':''}>${x}</option>`).join('')}</select></div><div class="field grow"><label>Opposition contains</label><input id="compare-opp" value="${e(cOpp)}" placeholder="e.g. Australia"/></div></div><div id="comparison-results"><div class="empty">Loading recorded innings…</div></div>`;return body}
function matchExplorer(all){if(!report?.manifest?.matchCount)return empty();let opts=[...(report.players||[]),...(report.historicalPlayers||[])].slice().sort((a,b)=>a.name.localeCompare(b.name));let selected=c1||opts[0]?.playerId;let innings=all.filter(x=>x.p===selected&&(cf==='all'||x.f===cf)&&(cVenue==='All'||x.reg===cVenue)&&(!cOpp||x.o.toLowerCase().includes(cOpp.toLowerCase()))).sort((a,b)=>msort==='date'?b.d.localeCompare(a.d):b.r-a.r);let body=`<div class="toolbar"><div class="field grow"><label>Batter</label><select id="match-player">${opts.map(x=>`<option value="${e(x.playerId)}" ${x.playerId===selected?'selected':''}>${e(x.name)}</option>`).join('')}</select></div><div class="field"><label>Format</label><select id="compare-format">${['all','odi','test','t20i'].map(f=>`<option value="${f}" ${cf===f?'selected':''}>${f==='all'?'All formats':fmt(f)}</option>`).join('')}</select></div><div class="field"><label>Region</label><select id="compare-venue">${['All','India','SENA','Other'].map(x=>`<option ${cVenue===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Against</label><input id="compare-opp" placeholder="Opposition" value="${e(cOpp)}"/></div><div class="field"><label>Sort</label><select id="match-sort"><option value="date" ${msort==='date'?'selected':''}>Latest</option><option value="runs" ${msort==='runs'?'selected':''}>Most runs</option></select></div></div>`;body+=`<p class="footnote">${num(innings.length)} recorded innings found. Older historical scorecard extracts may omit individual teammate identities; their combined teammate runs are still used in historical carry calculations.</p>`;body+=innings.length?`<div class="table-wrap"><table class="rank-table"><thead><tr><th>Date</th><th>Format</th><th>Opposition</th><th>Region</th><th class="num">Runs</th><th class="num">Balls</th><th class="num">Expected runs</th><th class="num">Peer factor</th><th>Same-match peers</th></tr></thead><tbody>`+innings.slice(0,200).map(x=>`<tr><td>${e(x.d)}</td><td>${e(x.f.toUpperCase())}</td><td>${e(x.o)}</td><td>${e(x.reg)}</td><td class="num primary-val">${num(x.r)}</td><td class="num">${num(x.b)}</td><td class="num">${num(x.er,1)}</td><td class="num">${num(x.pr,2)}</td><td><button class="player-link" data-innings="${e(x.i)}">See teammates →</button></td></tr>`).join('')+'</tbody></table></div>':empty('No innings match this filter');body+='<div id="team-display"></div>';return body}
function displayTeammates(innId){let all=allInnings||focus;let rows=all.filter(x=>x.i===innId).sort((a,b)=>(a.pos||999)-(b.pos||999));let target=$('#team-display');if(!target)return;target.innerHTML=`<section class="section"><div class="section-heading"><h2>Same innings · observed teammates</h2><span class="sub">Match ${e(rows[0]?.m||'')}</span></div><div class="table-wrap"><table class="rank-table"><thead><tr><th>Batter</th><th class="num">Runs</th><th class="num">Balls</th><th class="num">Expected</th><th>Out?</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${e(x.n)}</td><td class="num">${num(x.r)}</td><td class="num">${num(x.b)}</td><td class="num">${num(x.er,1)}</td><td>${x.x?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div>${rows.some(x=>x.s===1)?`<p class="footnote">Historical extract shows selected players only. Other teammates combined: ${num(rows[0]?.teammateRuns)} runs (from the original team batting card). No batting order or missing ball-count values are inferred.</p>`:''}</section>`;target.scrollIntoView({behavior:'smooth',block:'start'})}
function methodology(){return `<div class="takeaway"><div><small>FULL TRANSPARENCY · NOT A BLACK BOX</small><h2>Three separate answers. No forced single-number verdict.</h2><p>Quality measures a player's performance against contemporaneous opportunity; Carry shows how far they exceeded teammates; Greatness rewards sustained quality and cumulative value. Each has different limitations.</p></div><div class="evidence"><div class="insight">100 = contextual baseline for the <strong>Quality</strong> score.</div><div class="insight">Bowling and same-match estimates are <strong>partially pooled</strong>.</div><div class="insight"><strong>Historical equivalence</strong> needs complete scorecards and matched coverage.</div></div></div><section class="section"><div class="section-heading"><h2>The three headline indices</h2></div><div class="method-grid"><div class="method-card"><div class="k-label">01 · ABILITY</div><h3>Batting Quality</h3><p>Compare actual runs and dismissals with expected outcomes for an era and batting role, partially adjusted for opposing bowling and same-match scoring environment. A shrunk weighted geometric mean yields the index.</p></div><div class="method-card"><div class="k-label">02 · DEPENDENCY</div><h3>Team Carry</h3><p>Within each team's own innings, compare the batter with teammates' observed runs relative to their context-matched expectations. Also show team run share and extra runs versus peers. Do not mistake this for a causal effect.</p></div><div class="method-card"><div class="k-label">03 · LEGACY</div><h3>Career Greatness</h3><p>Combine a shrinkage-adjusted quality advantage, sample-size information and cumulative runs above expected. Tests + ODIs and all-three composites require eligibility in every included format.</p></div></div></section><section class="section"><div class="section-heading"><h2>Calculation specification · research v0.2</h2></div><div class="equation">Reference cohorts = same FORMAT × calendar year (±1, 2, 4, 7 or 12) × batting ROLE.
Expected runs = expected runs/ball × balls faced × exp(-0.35 × bowling strength) × match scoring factor.
Expected outs = expected outs/ball × balls faced × exp(+0.25 × bowling strength) × match-factor^(-0.25).
Run ratio = (actual runs + 25) / (expected runs + 25).
Survival ratio = (expected outs + 3) / (actual outs + 3).
Quality = 100 × exp( (w × ln(run ratio) + (1−w) × ln(survival ratio)) × n/(n+28)).
Test w=0.32 · ODI w=0.58 · T20I w=0.78.
Carry = 100 × (actual runs +25) / (expected runs × peer expected-adjusted rate +25).
Greatness = 100 + (Quality−100)×√min(1,n/140) + 10×asinh(runs above expected/1250).
All-format Quality = geometric mean of eligible individual-format Quality scores.</div><p class="footnote">These are specified research choices, not statistically optimized coefficients. The index is not a causal estimate of batting skill; sensitivity analysis and external validation are required before making definitive all-time claims.</p></section><section class="section"><div class="section-heading"><h2>How each requested control is handled</h2></div><div class="method-grid">${[['Era & changing run environment','Contemporary format-year-role baselines; period controls prevent raw averages being treated as equivalent.','IN MODEL'],['Pitch & match conditions','Partially pooled scoring conditions estimated from other batters on both sides of the same match.','PROXY'],['Opposition quality','Nearby-year bowler runs conceded and credited wicket rates; shrink toward peers and map each batter’s exposures.','IN MODERN MODEL'],['Skill of teammates','Same-innings expected-run-adjusted teammate comparison; excludes target’s own runs.','IN MODEL'],['Venue & geography','Home/away, India, SENA, other, unknown. Unknown venues are not guessed.','DESCRIPTIVE SLICE'],['Era-specific rule changes','ICC rules timeline and era comparisons; regression discontinuity and counterfactual design are pending.','RESEARCH QUEUE'],['Big matches & chases','World Cups and verified final/semi-final event metadata; chasing proxy for second innings.','LIMITED COVERAGE'],['Peak, consistency and longevity','Career quality, adjusted surplus and volume; peak-period and volatility tests are next.','PARTIAL'],['Pre-2002 archive','Structured scorecard importer; must obtain rights to bulk redistribute original records.','BLOCKED ON SOURCE']].map(([h,p,s])=>`<div class="method-card"><div class="k-label">${s}</div><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></section><section class="section"><div class="section-heading"><h2>Rule-change timeline</h2></div><div class="rules"><div class="rule"><time>1 OCT 2011 · ODIs</time><strong>Two new balls, one from each end</strong><p>Changes ball condition and balance between bat and ball. <a target="_blank" href="https://www.icc-cricket.com/news/amendments-to-playing-conditions-take-effect-from-1-october-x1706">ICC documentation ↗</a></p></div><div class="rule"><time>5 JUL 2015 · ODIs</time><strong>Batting Powerplay removed</strong><p>Also changed death-over fielding restrictions and no-ball free hits. <a target="_blank" href="https://www.icc-cricket.com/news/new-playing-conditions-come-into-effect">ICC documentation ↗</a></p></div><div class="rule"><time>2025 · ODIs</time><strong>Change to ball use after 34 overs</strong><p>ICC announced that teams would select one ball after over 34. <a target="_blank" href="https://www.icc-cricket.com/news/several-changes-made-to-icc-playing-conditions">ICC documentation ↗</a></p></div><div class="rule"><time>MODEL DESIGN</time><strong>Distinguish rules from eras</strong><p>Event dates serve as planned features and breakpoints, not proof that a rule caused an observed scoring change.</p></div></div></section>`}
function coverage(){let m=report?.manifest||{},b=m.byFormat||{};return `${stats([['Observed Tests',num(b.test||0),'Cricsheet source matches'],['Observed ODIs',num(b.odi||0),'Cricsheet source matches'],['Observed T20Is',num(b.t20i||0),'Cricsheet source matches'],['Historical imported',report?.metadata?.hasHistoricalScorecards?'Yes':'No','Scorecard-only external source']])}<div class="takeaway"><div><small>DATA PROVENANCE FIRST</small><h2>Publicly viewable is not the same as redistributable.</h2><p>Each published ranking must have a traceable match ID, known data source, and transparent missingness. Historic scorecards are essential but cannot be silently copied wholesale from sites without a reusable data licence.</p></div><div class="evidence"><div class="insight"><strong>Recorded match scope:</strong> ${num(m.matchCount||0)} actual ingested games</div><div class="insight"><strong>Date range:</strong> ${e(m.earliestDate||'not loaded')} to ${e(m.latestDate||'not loaded')}</div><div class="insight"><strong>Official all-time archive:</strong> incomplete / unverified</div><div class="insight"><strong>ICC retired-career run checks:</strong> ${num(report?.careerValidation?.passingCareers||0)} of ${num(report?.careerValidation?.checkedCareers||0)} passing</div><div class="insight"><strong>Historical scorecard observations:</strong> ${num(report?.metadata?.historicalObservedInnings||0)} · <strong>Additional historical matches:</strong> ${num(report?.metadata?.historicalDistinctMatchesAfterDedup||0)}</div></div></div><section class="section"><div class="section-heading"><h2>Public datasets investigated</h2><span class="sub">Primary / contextual / restricted sources</span></div><div class="data-list">${[
['Cricsheet — official original JSON','Open downloadable ball-by-ball records for international formats; men’s ZIPs ingested in project workflow. ODC-BY 1.0; historical gaps and withheld matches.','https://cricsheet.org/downloads/','INGESTION SOURCE'],
['Duncan Golicher — historical scorecard innings','2017 ESPNcricinfo-derived player and team innings snapshots for Tests, ODIs and T20Is. Historical workflow import is configured; raw redistribution licence unknown, completeness NOT verified.','https://github.com/dgolicher/cricket','HISTORICAL IMPORT'],
['Cricsheet — people register','Stable player identifiers and cross-site keys reduce duplicate or ambiguous-name errors.','https://cricsheet.org/register/','IDENTITY'],
['Cricket Database — historical scorecards','Lists historical Tests since 1877 and ODIs since 1971; detailed API has quota and older-match limitations. NOT an ingested source.','https://cricketdatabase.com/','RESEARCHED'],
['cricketdata R — historical Cricinfo statistics','R package provides career and innings queries; sourcing from ESPN requires observing ESPN terms. Not silently fetched or republished.','https://pkg.robjhyndman.com/cricketdata/','RESEARCHED'],
['CricArcade — historical archives','Reports 2,537 Test scorecards to March 2024 and 4,981 men’s ODIs to August 2026. No permission for bulk redistribution was established.','https://cricarcade.com/data-sources','RESEARCHED'],
['Doosra — Hugging Face archive','Independent Cricsheet-derived parquet source with match, batting-innings and delivery tables. Useful for validation, not an independent historical source.','https://huggingface.co/datasets/Sarthak213/doosra-cricket','VALIDATION OPTION'],
['ICC — playing conditions','Official ODI rules history useful for historical breakpoints; rules are explanatory covariates, not conclusive causal effects.','https://www.icc-cricket.com/news/new-playing-conditions-come-into-effect','RULE REFERENCE']].map(([name,desc,url,st])=>`<div class="data-item"><div><div class="k-label">${e(st)}</div><strong>${e(name)}</strong><p>${e(desc)}</p></div><a target="_blank" rel="noopener" href="${e(url)}">Open source ↗</a></div>`).join('')}</div></section><section class="section"><div class="section-heading"><h2>Coverage and analytical caveats</h2></div><div class="cards-two"><div class="call"><h3>Modern delivery detail</h3><p>Cricsheet international JSON presently begins around 2001 for men's Tests, 2002 for ODIs and 2005 for T20Is. Specific missing and withheld matches cause incomplete career totals even in modern years.</p><p><strong>Important:</strong> Figures labelled observed are not official complete career statistics.</p></div><div class="call"><h3>Historic scorecards</h3><p>Modern model fields such as individual bowler exposure cannot be inferred from historical scorecards. Historical scorecards must use a separate, explicitly calibrated common-denominator model that is reproducible over both modern and older eras.</p><p><strong>Important:</strong> A modern-only cross-format composite is not a defensible claim of greatest batter since 1877.</p></div></div></section><section class="section"><div class="section-heading"><h2>Reproducibility manifest</h2></div><div class="equation">${e(JSON.stringify({source:m.source||'not ingested',matchCount:m.matchCount||0,byFormat:m.byFormat||{},earliestDate:m.earliestDate||null,latestDate:m.latestDate||null,archiveSHA256:m.sha256||{},historicalImported:!!report?.metadata?.hasHistoricalScorecards},null,2))}</div></section>`}
function updateResults(){let target=$('#comparison-results');if(!target)return;let rows=allInnings||focus;target.innerHTML=comparisonOutput(rows);if(!allInnings)loadAllInnings().then(all=>{if(view==='compare'&&$('#comparison-results'))$('#comparison-results').innerHTML=comparisonOutput(all)})}
async function refreshMatches(){let target=$('#page-body');if(!target)return;target.innerHTML=matchExplorer(allInnings||focus);if(!allInnings){let data=await loadAllInnings();if(view==='matches')target.innerHTML=matchExplorer(data)}}
function draw(){const page=view==='profile'?'profile':view;header(page==='profile'?'overview':page);if(page==='profile'){$('#page-heading').innerHTML=`The <em>career</em> of ${e(playerInfo(selectedPlayer)?.name||'a batter')}`;$('#page-description').textContent='Each available source-backed performance record, contextualized against its era and teammates.'}
const target=$('#page-body');if(page==='overview')target.innerHTML=showOverview();else if(['odi','test','t20i'].includes(page))target.innerHTML=formatPage(page);else if(['test_odi','all_three'].includes(page))target.innerHTML=combinedPage(page);else if(page==='profile')target.innerHTML=profilePage(selectedPlayer);else if(page==='compare'){target.innerHTML=comparisonPage();if(c1&&$('#compare-one')){$('#compare-one').value=c1;$('#compare-two').value=c2}updateResults()}else if(page==='matches')refreshMatches();else if(page==='methodology')target.innerHTML=methodology();else if(page==='coverage')target.innerHTML=coverage();status()}
function wire(){document.addEventListener('click',ev=>{let n=ev.target.closest('[data-page]');if(n){nav(n.dataset.page);return}n=ev.target.closest('[data-goto]');if(n){nav(n.dataset.goto);return}n=ev.target.closest('[data-player]');if(n){nav('profile',n.dataset.player);return}n=ev.target.closest('[data-innings]');if(n){displayTeammates(n.dataset.innings);return}n=ev.target.closest('[data-sort]');if(n){if(sortKey===n.dataset.sort)sortDesc=!sortDesc;else{sortKey=n.dataset.sort;sortDesc=true}draw()}});
document.addEventListener('change',ev=>{let id=ev.target.id,v=ev.target.value;if(id==='country-filter'){country=v;draw()}if(id==='region-filter'){region=v;draw()}if(id==='metric-filter'){metric=v;sortKey='shownValue';sortDesc=true;draw()}if(id==='minimum-filter'){minInnings=+v;draw()}if(id==='compare-one'){c1=v;updateResults()}if(id==='compare-two'){c2=v;updateResults()}if(id==='compare-format'){cf=v;if(view==='matches')refreshMatches();else updateResults()}if(id==='compare-mode'){cmode=v;updateResults()}if(id==='compare-venue'){cVenue=v;if(view==='matches')refreshMatches();else updateResults()}if(id==='match-player'){c1=v;refreshMatches()}if(id==='match-sort'){msort=v;refreshMatches()}});
document.addEventListener('input',ev=>{let id=ev.target.id;if(id==='search-batter'){let active=document.activeElement;query=ev.target.value;let start=active.selectionStart;draw();let next=$('#search-batter');next?.focus();next?.setSelectionRange(start,start)}if(id==='weight-control'){weight=+ev.target.value/100;draw()}if(id==='compare-opp'){cOpp=ev.target.value;let start=ev.target.selectionStart;if(view==='matches')refreshMatches();else updateResults();let next=$('#compare-opp');next?.focus();next?.setSelectionRange(start,start)}});
$('#menu-button').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));window.addEventListener('hashchange',()=>{const h=decodeURIComponent(window.location.hash.slice(1));if(h.startsWith('profile/')){view='profile';selectedPlayer=h.slice(8)}else if(sections[h])view=h;draw()})}
async function startup(){if(!report){try{const response=await fetch('data/report.json');if(response.ok)report=await response.json()}catch(_){}}if(!focus.length){try{const response=await fetch('data/focus-innings.json');if(response.ok)focus=await response.json()}catch(_){}}focus.push(...(report?.historicalFocus||[]));const route=decodeURIComponent(window.location.hash.slice(1));if(route.startsWith('profile/')){view='profile';selectedPlayer=route.slice(8)}else if(sections[route])view=route;wire();draw()}
startup();
})();
